Command Editor.read executed: path='/workspace/qr-restaurant-app/src/App.tsx' content='001|import { useState, useEffect } from 'react';
002|import { AppStage, Language, OrderItem, Restaurant, Bill, Payment } from './types';
003|import { QRScanner } from './components/QRScanner';
004|import { RestaurantInfo } from './components/RestaurantInfo';
005|import { TableSelector } from './components/TableSelector';
006|import { WaitingScreen } from './components/WaitingScreen';
007|import { TableReadyScreen } from './components/TableReadyScreen';
008|import { MenuDisplay } from './components/MenuDisplay';
009|import { DiningScreen } from './components/DiningScreen';
010|import { BillPayment } from './components/BillPayment';
011|import { PaymentCompleteScreen } from './components/PaymentCompleteScreen';
012|import { ProximityWarning } from './components/ProximityWarning';
013|import { DemoInfoCard } from './components/DemoInfoCard';
014|import { mockRestaurants } from './data/mockRestaurants';
015|import { Button } from './components/ui/button';
016|import { Globe } from 'lucide-react';
017|
018|export default function App() {
019|  // Detect phone language (simulated - in real app would use navigator.language)
020|  const [language, setLanguage] = useState<Language>('en');
021|  const [stage, setStage] = useState<AppStage>('qr-scan');
022|  const [currentRestaurant, setCurrentRestaurant] = useState<Restaurant | null>(null);
023|  const [selectedTableId, setSelectedTableId] = useState<string | null>(null);
024|  const [currentOrders, setCurrentOrders] = useState<OrderItem[]>([]);
025|  const [drinkOrders, setDrinkOrders] = useState<OrderItem[]>([]);
026|  const [proximityDistance, setProximityDistance] = useState(10); // meters from restaurant
027|  const [bill, setBill] = useState<Bill | null>(null);
028|  const [mockPayments, setMockPayments] = useState<Payment[]>([]);
029|
030|  // Auto-detect language on mount (simulated)
031|  useEffect(() => {
032|    const browserLang = navigator.language.toLowerCase();
033|    if (browserLang.startsWith('es')) setLanguage('es');
034|    else if (browserLang.startsWith('fr')) setLanguage('fr');
035|    else if (browserLang.startsWith('de')) setLanguage('de');
036|    else if (browserLang.startsWith('ja')) setLanguage('ja');
037|    else if (browserLang.startsWith('ar')) setLanguage('ar');
038|    else if (browserLang.startsWith('zh')) setLanguage('zh');
039|    else setLanguage('en');
040|  }, []);
041|
042|  // Simulate proximity changes
043|  useEffect(() => {
044|    if (stage === 'waiting' && drinkOrders.length > 0) {
045|      // Simulate random proximity changes for demo
046|      const interval = setInterval(() => {
047|        setProximityDistance(prev => {
048|          const change = (Math.random() - 0.5) * 10;
049|          return Math.max(0, Math.min(100, prev + change));
050|        });
051|      }, 3000);
052|      return () => clearInterval(interval);
053|    }
054|  }, [stage, drinkOrders]);
055|
056|  const handleQRScan = (restaurantId: string) => {
057|    const restaurant = mockRestaurants.find(r => r.id === restaurantId);
058|    if (restaurant) {
059|      setCurrentRestaurant(restaurant);
060|      setStage('restaurant-info');
061|    }
062|  };
063|
064|  const handleTableSelection = (tableId: string | null) => {
065|    setSelectedTableId(tableId);
066|    setStage('waiting');
067|  };
068|
069|  const handleOrderDrinks = () => {
070|    setStage('ordering-drinks');
071|  };
072|
073|  const handleDrinkOrderPlaced = (items: OrderItem[]) => {
074|    setDrinkOrders(items);
075|    setCurrentOrders(prev => [...prev, ...items]);
076|    setStage('waiting');
077|  };
078|
079|  const handleTableReady = () => {
080|    setStage('table-ready');
081|  };
082|
083|  const handleProceedToTable = () => {
084|    // Proximity check is now handled by ProximityWarning component
085|    setStage('ordering-food');
086|  };
087|
088|  const handleChargeAndReleaseTable = () => {
089|    const drinkTotal = drinkOrders.reduce((sum, item) => sum + item.menuItem.price * item.quantity, 0);
090|    alert(`Card charged $${drinkTotal.toFixed(2)} for drinks. Table has been released to next person on waitlist.`);
091|    // Reset to start - user lost their table
092|    setStage('qr-scan');
093|    setCurrentRestaurant(null);
094|    setSelectedTableId(null);
095|    setCurrentOrders([]);
096|    setDrinkOrders([]);
097|  };
098|
099|  const handleFoodOrderPlaced = (items: OrderItem[]) => {
100|    setCurrentOrders(prev => [...prev, ...items]);
101|    setStage('dining');
102|  };
103|
104|  const handleContinueOrdering = () => {
105|    setStage('ordering-food');
106|  };
107|
108|  const handleRequestBill = () => {
109|    const subtotal = currentOrders.reduce((sum, item) => sum + item.menuItem.price * item.quantity, 0);
110|    const tax = subtotal * 0.1;
111|    const tip = subtotal * 0.15;
112|    
113|    setBill({
114|      items: currentOrders,
115|      subtotal,
116|      tax,
117|      tip,
118|      total: subtotal + tax + tip,
119|      payments: mockPayments,
120|    });
121|    setStage('payment');
122|  };
123|
124|  const handlePaymentComplete = (paidAmount?: number, paidItems?: string[]) => {
125|    // Reset to initial state
126|    setStage('qr-scan');
127|    setCurrentRestaurant(null);
128|    setSelectedTableId(null);
129|    setCurrentOrders([]);
130|    setDrinkOrders([]);
131|    setBill(null);
132|    setMockPayments([]);
133|  };
134|
135|  const selectedTable = currentRestaurant?.tables.find(t => t.id === selectedTableId);
136|
137|  // Language selector (for demo purposes)
138|  const LanguageSelector = () => (
139|    <div className="fixed top-4 right-4 z-50">
140|      <select
141|        value={language}
142|        onChange={(e) => setLanguage(e.target.value as Language)}
143|        className="px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm flex items-center gap-2"
144|      >
145|        <option value="en">🇬🇧 English</option>
146|        <option value="es">🇪🇸 Español</option>
147|        <option value="fr">🇫🇷 Français</option>
148|        <option value="de">🇩🇪 Deutsch</option>
149|        <option value="ja">🇯🇵 日本語</option>
150|        <option value="ar">🇸🇦 العربية</option>
151|        <option value="zh">🇨🇳 中文</option>
152|      </select>
153|    </div>
154|  );
155|
156|  // Simulate other people paying at terminal
157|  const SimulateTerminalPayment = () => {
158|    if (stage !== 'payment' || !bill) return null;
159|    
160|    return (
161|      <div className="fixed bottom-24 right-4 z-50">
162|        <Button
163|          onClick={() => {
164|            const payment: Payment = {
165|              userId: `user-${mockPayments.length + 1}`,
166|              userName: `Customer ${mockPayments.length + 1}`,
167|              amount: 25,
168|              paidAt: new Date(),
169|            };
170|            setMockPayments(prev => [...prev, payment]);
171|            setBill(prev => prev ? { ...prev, payments: [...prev.payments, payment] } : null);
172|          }}
173|          variant="outline"
174|          size="sm"
175|        >
176|          Simulate Terminal Payment
177|        </Button>
178|      </div>
179|    );
180|  };
181|
182|  // Distance simulator for demo
183|  const DistanceSimulator = () => {
184|    if (stage !== 'waiting' || drinkOrders.length === 0) return null;
185|    
186|    return (
187|      <div className="fixed bottom-24 left-4 z-50 bg-white p-3 rounded-lg shadow-lg border">
188|        <p className="text-xs mb-2">Demo: Distance Control</p>
189|        <input
190|          type="range"
191|          min="0"
192|          max="100"
193|          value={proximityDistance}
194|          onChange={(e) => setProximityDistance(Number(e.target.value))}
195|          className="w-32"
196|        />
197|        <p className="text-xs mt-1">{proximityDistance}m</p>
198|      </div>
199|    );
200|  };
201|
202|  return (
203|    <div className="min-h-screen">
204|      {stage === 'qr-scan' && <DemoInfoCard />}
205|      
206|      <LanguageSelector />
207|      <SimulateTerminalPayment />
208|      <DistanceSimulator />
209|      
210|      {stage === 'waiting' && drinkOrders.length > 0 && (
211|        <ProximityWarning 
212|          distance={proximityDistance} 
213|          language={language} 
214|          drinkTotal={drinkOrders.reduce((sum, item) => sum + item.menuItem.price * item.quantity, 0)}
215|          onChargeAndRelease={handleChargeAndReleaseTable}
216|        />
217|      )}
218|
219|      {stage === 'qr-scan' && (
220|        <QRScanner language={language} onScan={handleQRScan} />
221|      )}
222|
223|      {stage === 'restaurant-info' && currentRestaurant && (
224|        <RestaurantInfo
225|          restaurant={currentRestaurant}
226|          language={language}
227|          onContinue={() => setStage('table-selection')}
228|        />
229|      )}
230|
231|      {stage === 'table-selection' && currentRestaurant && (
232|        <TableSelector
233|          tables={currentRestaurant.tables}
234|          language={language}
235|          onSelectTable={handleTableSelection}
236|        />
237|      )}
238|
239|      {stage === 'waiting' && currentRestaurant && (
240|        <WaitingScreen
241|          language={language}
242|          estimatedWaitTime={currentRestaurant.waitTime}
243|          onTableReady={handleTableReady}
244|          onOrderDrinks={handleOrderDrinks}
245|        />
246|      )}
247|
248|      {stage === 'ordering-drinks' && currentRestaurant && (
249|        <MenuDisplay
250|          drinks={currentRestaurant.menu.drinks}
251|          food={currentRestaurant.menu.food}
252|          language={language}
253|          onPlaceOrder={handleDrinkOrderPlaced}
254|          isDrinksOnly={true}
255|        />
256|      )}
257|
258|      {stage === 'table-ready' && selectedTable && (
259|        <TableReadyScreen
260|          language={language}
261|          tableNumber={selectedTable.number}
262|          onProceed={handleProceedToTable}
263|        />
264|      )}
265|
266|      {stage === 'ordering-food' && currentRestaurant && (
267|        <MenuDisplay
268|          drinks={currentRestaurant.menu.drinks}
269|          food={currentRestaurant.menu.food}
270|          language={language}
271|          onPlaceOrder={handleFoodOrderPlaced}
272|          isDrinksOnly={false}
273|        />
274|      )}
275|
276|      {stage === 'dining' && selectedTable && (
277|        <DiningScreen
278|          language={language}
279|          currentOrders={currentOrders}
280|          tableNumber={selectedTable.number}
281|          onContinueOrdering={handleContinueOrdering}
282|          onRequestBill={handleRequestBill}
283|        />
284|      )}
285|
286|      {stage === 'payment' && bill && (
287|        <BillPayment
288|          bill={bill}
289|          language={language}
290|          onPaymentComplete={handlePaymentComplete}
291|        />
292|      )}
293|    </div>
294|  );
295|}'

